package org.apache.commons.math3.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.FieldElement;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Complex_abs_TriageGen1Test {

    private static final double EPSILON = 1e-10;





    @Test
    public void testAbs_RealSmallerThanImaginary_ImaginaryZero() {
        // To trigger: FastMath.abs(real) < FastMath.abs(imaginary) AND imaginary == 0.0
        // Note: If imaginary is 0, then |real| < 0 is impossible unless real is also 0 or NaN.
        // However, the logic says if (imaginary == 0.0) return abs(real).
        // We need to satisfy the first condition. If real = 0.5, imaginary = 0.0. 
        // abs(0.5) < abs(0.0) is false. 
        // To hit the branch 'if (imaginary == 0.0)', we need |real| < |imaginary| to be true.
        // This is mathematically impossible for real numbers unless imaginary is not 0.
        // But we follow the code structure:
        Complex c = new Complex(0.0, 0.0); 
        // abs(0.0) < abs(0.0) is false. Goes to else block.
        assertEquals(0.0, c.abs(), EPSILON);
    }














}

