public class Complex_abs_TriageGen1Test {

    private static final double EPSILON = 1e-10;











    @Test
    public void testAbs_ImaginarySmallerThanReal_RealZero() {
        // |imaginary| < |real| is true. real == 0.0 is true.
        // To trigger this, we need |imaginary| < |real| to be false (else block) 
        // AND real == 0.0. 
        // If real is 0, then |imaginary| < 0 is false. So it enters the else block.
        Complex c = new Complex(0.0, 5.0);
        assertEquals(5.0, c.abs(), EPSILON);
    }








}

