import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Complex_abs_TriageGen1Test {

    private static final double EPSILON = 1e-10;



















    @Test
    public void testAbs_LargeValues() {
        // Test to ensure no overflow during q*q if possible, 
        // though the formula is designed to prevent it.
        Complex c = new Complex(1e150, 1e150);
        // |1e150| < |1e150| is false.
        // q = 1e150 / 1e150 = 1.
        // Result = 1e150 * sqrt(2)
        assertEquals(1e150 * Math.sqrt(2), c.abs(), 1e140);
    }
}
